 "content": "def transform(grid):
    """Extend each edge of a solid color-2 rectangle outward as rays.

    Nonzero markers on a ray block extension on that particular side.
    """
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    out = [row[:] for row in grid]

    # The object is a solid rectangle; extend each unobstructed horizontal ray.
    for r in range(r0, r1 + 1):
        if not any(grid[r][c] != 0 for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2

    # Extend unobstructed vertical rays for each column in the rectangle.
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] != 0 for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
